      "support_status": "SUFFICIENT",
      "rationale": "P022 identifies overall tail change as an evaluation outcome alongside phase changes, failures and unfinished exports. P021 clarifies that these observations are proposed."
    }
  },
  "signal_basis": {
    "component_id": "C046_signal_basis",
    "value": "Evaluate the canary against comparable baseline traffic, recording predicted-phase and overall-tail changes together with failures and unfinished exports.",
    "scope": "Use predefined operating bounds, observation window and required exposure. Inadequate exposure or coverage makes the evaluation inconclusive; a short clean canary cannot establish resolution.",
