      "rationale": "The cited spans supply the comparison baseline, measured outcomes and exposure and coverage limits."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C046_stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
